class Bucket:
    def __init__(self, cnt):
        self.cnt = cnt
        self.keys = set()
        self.prev = None
        self.next = None


def counterQueries(ops):
    head, tail = Bucket(0), Bucket(1 << 60)
    head.next = tail
    tail.prev = head
    where = {}

    def insert_after(b, cnt):
        nb = Bucket(cnt)
        nb.prev = b
        nb.next = b.next
        b.next.prev = nb
        b.next = nb
        return nb

    def drop_if_empty(b):
        if b is not head and not b.keys:
            b.prev.next = b.next
            b.next.prev = b.prev

    out = []
    for t, k in ops:
        if t == 0:
            cur = where.get(k, head)
            nxt = cur.next
            if nxt.cnt != cur.cnt + 1:
                nxt = insert_after(cur, cur.cnt + 1)
            nxt.keys.add(k)
            where[k] = nxt
            cur.keys.discard(k)
            drop_if_empty(cur)
        elif t == 1:
            cur = where[k]
            if cur.cnt == 1:
                del where[k]
            else:
                pb = cur.prev
                if pb.cnt != cur.cnt - 1:
                    pb = insert_after(pb, cur.cnt - 1)
                pb.keys.add(k)
                where[k] = pb
            cur.keys.discard(k)
            drop_if_empty(cur)
        elif t == 2:
            out.append(tail.prev.cnt)
        else:
            out.append(0 if head.next is tail else head.next.cnt)
    return out
